using System.Text;
namespace PartnerPortal.Api.Infrastructure;
public sealed class CaptchaService { private readonly ICaptchaStore store; public CaptchaService(ICaptchaStore store) => this.store=store; public object Create() { var id=Guid.NewGuid().ToString(); var answer=Random.Shared.Next(10000,99999).ToString(); store.Put(id,answer,DateTime.UtcNow.AddMinutes(5)); var chars=new StringBuilder(); var colors=new[]{"#f47b20","#234b78"}; for(var i=0;i<answer.Length;i++){ var baseline=Random.Shared.Next(25,29); var x=56+i*21; var rotate=Random.Shared.Next(-5,6); chars.Append($"<text x=\"{x}\" y=\"{baseline}\" fill=\"{colors[i%2]}\" transform=\"rotate({rotate} {x} {baseline})\">{answer[i]}</text>"); } var svg=$"<svg xmlns='http://www.w3.org/2000/svg' width='190' height='38' viewBox='0 0 190 38'><g font-family='Arial, sans-serif' font-size='21' font-weight='600' letter-spacing='1'>{chars}</g></svg>"; return new { captchaId=id, image="data:image/svg+xml;base64,"+Convert.ToBase64String(Encoding.UTF8.GetBytes(svg)) }; } public bool Verify(string id,string answer) => store.Consume(id,answer); }
